<?php require dirname(__DIR__).'/config/config.php'; require dirname(__DIR__).'/vendor/autoload.php'; use App\Helpers\Security; use App\Models\Cacamba; use App\Models\Pedido; $u=Security::requireAuth(); $disponiveis=count(Cacamba::disponiveis()); $ativos=(int)db()->query("SELECT COUNT(*) FROM pedidos WHERE status IN ('confirmado','entregue')")->fetchColumn(); $clientes=(int)db()->query('SELECT COUNT(*) FROM clientes')->fetchColumn(); $faturamento=Pedido::faturamentoMes(); $recentes=Pedido::recentes(); ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="css/app.css"><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4"></script></head><body><nav class="navbar navbar-dark bg-primary"><div class="container-fluid"><span class="navbar-brand">Controle de Locação</span><span class="text-white">Olá, <?=Security::e($u['nome'])?> · <a class="text-white" href="logout.php">Sair</a></span></div></nav><div class="container-fluid py-4"><div class="row g-3"><div class="col-md-3"><div class="card kpi"><small>Caçambas disponíveis</small><strong><?=$disponiveis?></strong></div></div><div class="col-md-3"><div class="card kpi"><small>Pedidos ativos</small><strong><?=$ativos?></strong></div></div><div class="col-md-3"><div class="card kpi"><small>Clientes</small><strong><?=$clientes?></strong></div></div><div class="col-md-3"><div class="card kpi"><small>Faturamento do mês</small><strong>R$ <?=number_format($faturamento,2,',','.')?></strong></div></div></div><div class="row g-4 mt-1"><div class="col-lg-7"><div class="card p-3"><h5>Pedidos recentes</h5><div class="table-responsive"><table class="table align-middle"><thead><tr><th>ID</th><th>Cliente</th><th>Caçamba</th><th>Status</th><th>Valor</th></tr></thead><tbody><?php foreach($recentes as $r):?><tr><td>#<?=$r['id']?></td><td><?=Security::e($r['cliente'])?></td><td><?=Security::e($r['cacamba']??'-')?></td><td><span class="badge text-bg-primary"><?=Security::e($r['status'])?></span></td><td>R$ <?=number_format((float)$r['valor'],2,',','.')?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-5"><div class="card p-3"><h5>Ocupação</h5><canvas id="ocupacao"></canvas></div></div></div><div class="mt-4"><a class="btn btn-primary" href="clientes.php">Clientes</a> <a class="btn btn-outline-primary" href="cacambas.php">Caçambas</a></div></div><script>new Chart(document.getElementById('ocupacao'),{type:'doughnut',data:{labels:['Disponível','Em uso','Manutenção','Inativa'],datasets:[{data:[<?=$disponiveis?>,<?=((int)db()->query("SELECT COUNT(*) FROM cacambas WHERE status='em_uso'")->fetchColumn())?>,<?=((int)db()->query("SELECT COUNT(*) FROM cacambas WHERE status='manutencao'")->fetchColumn())?>,<?=((int)db()->query("SELECT COUNT(*) FROM cacambas WHERE status='inativa'")->fetchColumn())?>]}]}});</script></body></html>
